class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        # accumulate the total of land edges that exposed to water
        m, n = len(grid), len(grid[0])
        DIR = [0, 1, 0, -1, 0]
        queue = collections.deque()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    queue.append((i, j))

        perimeter = 0
        while queue:
            cell = queue.popleft()
            for i in range(4):
                nr, nc = cell[0] + DIR[i], cell[1] + DIR[i + 1]
                if (0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 0) or nr < 0 or nr >= m or nc <0 or nc >= n:
                    perimeter += 1


        return perimeter
